        check(read(()->((Integer)field(selectedPicker,"selected"))==1),"picker reopens on current episode");key(KeyEvent.KEYCODE_DPAD_RIGHT);check(read(()->((Integer)field(selectedPicker,"selected"))==20),"episode group navigates in place");key(KeyEvent.KEYCODE_BACK);check(read(()->field(activity,"choicePanel")==null&&!activity.isFinishing()),"Back closes picker before exiting playback");
