        check(read(()->((Integer)field(channels,"selected"))==1),"first system Down selects next channel after touch");picture("channels");SystemClock.sleep(6000);check(read(()->Boolean.TRUE.equals(call(channels,"open",new Class[]{}))),"channel picker does not auto-close while browsing");key(KeyEvent.KEYCODE_DPAD_CENTER);until(()->read(()->((Integer)field(activity,"playingIndex"))==1)&&playing(),"selected live channel plays");
        key(KeyEvent.KEYCODE_DPAD_DOWN);until(()->read(()->((Integer)field(activity,"playingIndex"))==2)&&playing(),"direct Down changes live channel");key(KeyEvent.KEYCODE_CHANNEL_UP);until(()->read(()->((Integer)field(activity,"playingIndex"))==3)&&playing(),"channel key changes live channel");
